*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body, #root {
  height: 100%;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 14px;
  color: #1f2937;
  background: #f9fafb;
}

/* ── Layout ───────────────────────────────────────────── */

.app-layout {
  display: flex;
  height: 100%;
}

.sidebar {
  width: 260px;
  min-width: 260px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: #fff;
  border-right: 1px solid #e5e7eb;
  overflow-y: auto;
}

.map-container {
  flex: 1;
  position: relative;
}

/* ── Sidebar header ───────────────────────────────────── */

.sidebar-header {
  padding-bottom: 12px;
  border-bottom: 1px solid #e5e7eb;
}

.app-title {
  font-size: 16px;
  font-weight: 700;
  color: #111827;
  line-height: 1.3;
}

.app-subtitle {
  font-size: 11px;
  color: #9ca3af;
  margin-top: 2px;
}

/* ── Search bar ───────────────────────────────────────── */

.search-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.search-bar input {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 13px;
  outline: none;
}

.search-bar input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59,130,246,0.2);
}

.search-bar button {
  padding: 6px 12px;
  background: #3b82f6;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
}

.search-bar button:disabled {
  opacity: 0.6;
  cursor: default;
}

.search-notfound {
  font-size: 12px;
  color: #ef4444;
  width: 100%;
}

/* ── Filter panel ─────────────────────────────────────── */

.filter-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.panel-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
}

.field-label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: #374151;
}

.field-label input[type="date"],
.field-label input[type="range"] {
  width: 100%;
}

.field-label input[type="date"] {
  padding: 5px 6px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 12px;
  outline: none;
}

.field-label input[type="date"]:focus {
  border-color: #3b82f6;
}

.field-label input[type="range"] {
  accent-color: #3b82f6;
}

/* ── Status badge ─────────────────────────────────────── */

.status {
  min-height: 32px;
}

.status-loading {
  font-size: 12px;
  color: #6b7280;
}

.status-count {
  font-size: 12px;
  font-weight: 600;
  color: #059669;
}

.status-error {
  font-size: 12px;
  color: #dc2626;
  line-height: 1.5;
}

/* ── Legend ───────────────────────────────────────────── */

.legend {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 12px;
  border-top: 1px solid #e5e7eb;
}

.legend-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #374151;
}

.dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}

