  padding: 6px 12px;
  background: #3b82f6;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
}

.search-bar button:disabled {
  opacity: 0.6;
  cursor: default;
}

.search-notfound {
  font-size: 12px;
  color: #ef4444;
  width: 100%;
}

