#!/bin/sh
# Format and lint staged files only
npx lint-staged

{
  "singleQuote": true,
  "trailingComma": "all",
  "semi": false,
  "printWidth": 100
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body, #root {
  height: 100%;
  width: 100%;
  overflow: hidden;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 14px;
  color: #1f2937;
}

/*
  Leaflet's own CSS sets background:#ddd on .leaflet-container.
  It is imported inside MapView.tsx so it loads after this file and wins.
  !important is the only reliable way to override it.
  #a8c8f0 matches the OSM ocean tile colour so the gap at min-zoom blends in.
*/
.leaflet-container {
  background: #a8c8f0 !important;
}

/* ── Layout ───────────────────────────────────────────── */

.app-layout {
  display: flex;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
  position: relative;
}

/* ── Sidebar ──────────────────────────────────────────── */

.sidebar {
  width: 260px;
  min-width: 260px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: #fff;
  border-right: 1px solid #e5e7eb;
  overflow-y: auto;
  z-index: 1000;
  /* desktop: always in flow */
  position: relative;
  flex-shrink: 0;
}

.map-container {
  flex: 1;
  position: relative;
  min-width: 0;
}

/* ── Sidebar header ───────────────────────────────────── */

.sidebar-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid #e5e7eb;
}

.app-title {
  font-size: 16px;
  font-weight: 700;
  color: #111827;
  line-height: 1.3;
}

.app-subtitle {
  font-size: 11px;
  color: #9ca3af;
  margin-top: 2px;
}

/* Close button — hidden on desktop */
.sidebar-close {
  display: none;
  background: none;
  border: none;
  font-size: 16px;
  color: #6b7280;
  cursor: pointer;
  padding: 2px 4px;
  line-height: 1;
  flex-shrink: 0;
}

/* Hamburger toggle — hidden on desktop */
.sidebar-toggle {
  display: none;
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 999;
  background: #fff;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 1px 4px rgba(0,0,0,0.15);
}

/* Backdrop — hidden on desktop */
.sidebar-backdrop {
  display: none;
}

/* ── Search bar ───────────────────────────────────────── */

.search-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.search-bar input {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 13px;
  outline: none;
}

.search-bar input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59,130,246,0.2);
}

.search-bar button {
  padding: 6px 12px;
  background: #3b82f6;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
}

.search-bar button:disabled {
  opacity: 0.6;
  cursor: default;
}

.search-notfound {
  font-size: 12px;
  color: #ef4444;
  width: 100%;
}

/* ── Filter panel ─────────────────────────────────────── */

.filter-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.panel-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
}

.field-label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: #374151;
}

.field-label input[type="date"],
.field-label input[type="range"] {
  width: 100%;
}

.field-label input[type="date"] {
  padding: 5px 6px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 12px;
  outline: none;
}

.field-label input[type="date"]:focus {
  border-color: #3b82f6;
}

.field-label input[type="range"] {
  accent-color: #3b82f6;
}

/* ── Status badge ─────────────────────────────────────── */

.status {
  min-height: 32px;
}

.status-loading {
  font-size: 12px;
  color: #6b7280;
}

.status-count {
  font-size: 12px;
  font-weight: 600;
  color: #059669;
}

.status-error {
  font-size: 12px;
  color: #dc2626;
  line-height: 1.5;
}

/* ── Legend ───────────────────────────────────────────── */

.legend {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 12px;
  border-top: 1px solid #e5e7eb;
}

.legend-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #374151;
}

.dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Responsive — tablet & mobile (≤ 768px) ───────────── */

@media (max-width: 768px) {
  /* Sidebar becomes a fixed overlay drawer */
  .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    height: 100%;
    width: 280px;
    transform: translateX(-100%);
    transition: transform 0.25s ease;
    box-shadow: 4px 0 16px rgba(0,0,0,0.15);
  }

  .sidebar--open {
    transform: translateX(0);
  }

  /* Map fills the full screen on mobile */
  .map-container {
    width: 100vw;
  }

  /* Show hamburger button */
  .sidebar-toggle {
    display: block;
  }

  /* Show close button inside sidebar */
  .sidebar-close {
    display: block;
  }

  /* Show backdrop when sidebar is open */
  .sidebar-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.3);
    z-index: 999;
  }
}

/* ── Responsive — small desktop (769px – 1024px) ─────── */

@media (min-width: 769px) and (max-width: 1024px) {
  .sidebar {
    width: 220px;
    min-width: 220px;
  }
}

