import { Controller, Get, Query } from '@nestjs/common';
import { EarthquakesService } from './earthquakes.service.js';
import { EarthquakeQueryDto } from './dto/earthquake-query.dto.js';

@Controller('earthquakes')
export class EarthquakesController {
  constructor(private readonly service: EarthquakesService) {}

  @Get()
  query(@Query() dto: EarthquakeQueryDto) {
    return this.service.query(dto);
  }

  @Get('count')
  count(@Query() dto: EarthquakeQueryDto) {
    return this.service.count(dto);
  }
}

import { IsISO8601, IsNumber, IsOptional } from 'class-validator';
import { Type } from 'class-transformer';

export class EarthquakeQueryDto {
  @IsISO8601()
  starttime: string;

  @IsISO8601()
  endtime: string;

  @IsOptional()
  @IsNumber()
  @Type(() => Number)
  minmagnitude?: number;

  @IsOptional()
  @IsNumber()
  @Type(() => Number)
  maxmagnitude?: number;

  @IsOptional()
  @IsNumber()
  @Type(() => Number)
  minlatitude?: number;

  @IsOptional()
  @IsNumber()
  @Type(() => Number)
  maxlatitude?: number;

  @IsOptional()
  @IsNumber()
  @Type(() => Number)
  minlongitude?: number;

  @IsOptional()
  @IsNumber()
  @Type(() => Number)
  maxlongitude?: number;
}

