export interface EarthquakeFilters {
  starttime: string
  endtime: string
  minmagnitude?: number
  maxmagnitude?: number
  minlatitude?: number
  maxlatitude?: number
  minlongitude?: number
  maxlongitude?: number
}

export interface EarthquakeFeature {
  type: 'Feature'
  id: string
  geometry: {
    type: 'Point'
    coordinates: [number, number, number] // [lon, lat, depth_km]
  }
  properties: {
    mag: number
    place: string
    time: number
    updated: number
    felt: number | null
    cdi: number | null
    mmi: number | null
    alert: 'green' | 'yellow' | 'orange' | 'red' | null
    status: 'reviewed' | 'automatic'
    tsunami: 0 | 1
    sig: number
    magType: string
    type: string
    title: string
    url: string
  }
}

export interface EarthquakeCollection {
  type: 'FeatureCollection'
  metadata: { count: number; generated: number; title: string }
  features: EarthquakeFeature[]
}

export interface CountResult {
  count: number
  maxAllowed: number
}

export interface TooManyError {
  error: 'too_many_events'
  count: number
}

function toQueryString(filters: EarthquakeFilters): string {
  const params = new URLSearchParams()
  for (const [key, value] of Object.entries(filters)) {
    if (value !== undefined) params.set(key, String(value))
  }
  return params.toString()
}

export async function fetchEarthquakes(
  filters: EarthquakeFilters,
): Promise<EarthquakeCollection> {
  const res = await fetch(`/api/earthquakes?${toQueryString(filters)}`)
  if (res.status === 422) {
    const body = (await res.json()) as TooManyError
    throw Object.assign(new Error('too_many_events'), body)
  }
  if (!res.ok) throw new Error('Could not load earthquake data. Please try again.')
  return res.json() as Promise<EarthquakeCollection>
}

export async function fetchCount(filters: EarthquakeFilters): Promise<CountResult> {
  const res = await fetch(`/api/earthquakes/count?${toQueryString(filters)}`)
  if (!res.ok) throw new Error('Could not load earthquake data. Please try again.')
  return res.json() as Promise<CountResult>
}

import { useEffect, useRef, useState } from 'react'
import type { EarthquakeCollection, EarthquakeFilters } from '../api/earthquakes'
import { fetchEarthquakes } from '../api/earthquakes'

interface Bounds {
  minLatitude: number
  maxLatitude: number
  minLongitude: number
  maxLongitude: number
}

interface UseEarthquakesResult {
  data: EarthquakeCollection | null
  loading: boolean
  error: string | null
  tooMany: boolean
  tooManyCount: number | null
}

export function useEarthquakes(
  bounds: Bounds | null,
  filters: Omit<EarthquakeFilters, 'minlatitude' | 'maxlatitude' | 'minlongitude' | 'maxlongitude'>,
): UseEarthquakesResult {
  const [data, setData] = useState<EarthquakeCollection | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [tooMany, setTooMany] = useState(false)
  const [tooManyCount, setTooManyCount] = useState<number | null>(null)

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const abortRef = useRef<AbortController | null>(null)

  useEffect(() => {
    if (!bounds) return

    if (debounceRef.current) clearTimeout(debounceRef.current)

    debounceRef.current = setTimeout(async () => {
      if (abortRef.current) abortRef.current.abort()
      abortRef.current = new AbortController()

      setLoading(true)
      setError(null)
      setTooMany(false)
      setTooManyCount(null)

      try {
        const params: EarthquakeFilters = {
          ...filters,
          minlatitude: bounds.minLatitude,
          maxlatitude: bounds.maxLatitude,
          minlongitude: bounds.minLongitude,
          maxlongitude: bounds.maxLongitude,
        }
        const result = await fetchEarthquakes(params)
        setData(result)
      } catch (err: unknown) {
        if (err instanceof Error && err.message === 'too_many_events') {
          const e = err as Error & { count?: number }
          setTooMany(true)
          setTooManyCount(e.count ?? null)
        } else if (err instanceof Error && err.name !== 'AbortError') {
          setError(err.message)
        }
      } finally {
        setLoading(false)
      }
    }, 500)

    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [
    bounds?.minLatitude,
    bounds?.maxLatitude,
    bounds?.minLongitude,
    bounds?.maxLongitude,
    filters.starttime,
    filters.endtime,
    filters.minmagnitude,
    filters.maxmagnitude,
  ])

  return { data, loading, error, tooMany, tooManyCount }
}

interface GeocoderResult {
  lat: number
  lon: number
  displayName: string
}

export async function geocode(placeName: string): Promise<GeocoderResult | null> {
  const params = new URLSearchParams({
    q: placeName,
    format: 'json',
    limit: '1',
  })
  const res = await fetch(
    `https://nominatim.openstreetmap.org/search?${params}`,
    { headers: { 'User-Agent': 'usgs-earthquake-dashboard/1.0' } },
  )
  if (!res.ok) return null
  const results = (await res.json()) as Array<{
    lat: string
    lon: string
    display_name: string
  }>
  if (!results.length) return null
  return {
    lat: parseFloat(results[0].lat),
    lon: parseFloat(results[0].lon),
    displayName: results[0].display_name,
  }
}

interface Props {
  starttime: string
  endtime: string
  minmagnitude: number
  onStarttimeChange: (v: string) => void
  onEndtimeChange: (v: string) => void
  onMinmagnitudeChange: (v: number) => void
  count: number | null
  loading: boolean
  tooMany: boolean
  tooManyCount: number | null
  error: string | null
}

export default function FilterPanel({
  starttime,
  endtime,
  minmagnitude,
  onStarttimeChange,
  onEndtimeChange,
  onMinmagnitudeChange,
  count,
  loading,
  tooMany,
  tooManyCount,
  error,
}: Props) {
  return (
    <div className="filter-panel">
      <h2 className="panel-title">Filters</h2>

      <label className="field-label">
        Start date
        <input
          type="date"
          value={starttime}
          max={endtime}
          onChange={(e) => onStarttimeChange(e.target.value)}
        />
      </label>

      <label className="field-label">
        End date
        <input
          type="date"
          value={endtime}
          min={starttime}
          onChange={(e) => onEndtimeChange(e.target.value)}
        />
      </label>

      <label className="field-label">
        Min magnitude — <strong>M{minmagnitude.toFixed(1)}</strong>
        <input
          type="range"
          min={0}
          max={9}
          step={0.5}
          value={minmagnitude}
          onChange={(e) => onMinmagnitudeChange(parseFloat(e.target.value))}
        />
      </label>

      <div className="status">
        {loading && <span className="status-loading">Loading…</span>}
        {!loading && tooMany && (
          <span className="status-error">
            Too many events ({tooManyCount?.toLocaleString()}).
            <br />Zoom in or raise magnitude.
          </span>
        )}
        {!loading && error && (
          <span className="status-error">{error}</span>
        )}
        {!loading && !tooMany && !error && count !== null && (
          <span className="status-count">
            {count.toLocaleString()} event{count !== 1 ? 's' : ''}
          </span>
        )}
      </div>
    </div>
  )
}

import { useRef, useState } from 'react'
import { geocode } from '../hooks/useGeocoder'
import type { MapViewHandle } from './MapView'

interface Props {
  mapRef: React.RefObject<MapViewHandle | null>
}

export default function SearchBar({ mapRef }: Props) {
  const [query, setQuery] = useState('')
  const [status, setStatus] = useState<'idle' | 'loading' | 'notfound'>('idle')
  const inputRef = useRef<HTMLInputElement>(null)

  async function handleSearch(e: React.FormEvent) {
    e.preventDefault()
    if (!query.trim()) return
    setStatus('loading')
    const result = await geocode(query.trim())
    if (!result) {
      setStatus('notfound')
      return
    }
    setStatus('idle')
    mapRef.current?.flyTo(result.lat, result.lon, 8)
    inputRef.current?.blur()
  }

  return (
    <form className="search-bar" onSubmit={handleSearch}>
      <input
        ref={inputRef}
        type="text"
        placeholder="Search place…"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value)
          setStatus('idle')
        }}
      />
      <button type="submit" disabled={status === 'loading'}>
        {status === 'loading' ? '…' : 'Go'}
      </button>
      {status === 'notfound' && (
        <span className="search-notfound">Not found</span>
      )}
    </form>
  )
}

import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import { forwardRef, useEffect, useImperativeHandle, useRef } from 'react'
import type { EarthquakeFeature } from '../api/earthquakes'

interface Bounds {
  minLatitude: number
  maxLatitude: number
  minLongitude: number
  maxLongitude: number
}

interface Props {
  features: EarthquakeFeature[]
  onBoundsChange: (bounds: Bounds) => void
}

export interface MapViewHandle {
  flyTo: (lat: number, lon: number, zoom?: number) => void
}

function depthColor(depth: number): string {
  if (depth < 70) return '#22c55e'   // green — shallow
  if (depth < 300) return '#f59e0b'  // amber — intermediate
  return '#ef4444'                   // red — deep
}

function magRadius(mag: number): number {
  return Math.max(4, mag * 3)
}

function formatTime(epochMs: number): string {
  return new Date(epochMs).toUTCString()
}

const MapView = forwardRef<MapViewHandle, Props>(({ features, onBoundsChange }, ref) => {
  const containerRef = useRef<HTMLDivElement>(null)
  const mapRef = useRef<L.Map | null>(null)
  const layerRef = useRef<L.LayerGroup | null>(null)

  useImperativeHandle(ref, () => ({
    flyTo(lat, lon, zoom = 8) {
      mapRef.current?.flyTo([lat, lon], zoom)
    },
  }))

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return

    const map = L.map(containerRef.current, {
      minZoom: 2,
      maxBounds: L.latLngBounds(L.latLng(-90, -180), L.latLng(90, 180)),
      maxBoundsViscosity: 1.0,
    }).setView([20, 0], 2)
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
      maxZoom: 18,
      noWrap: true,
    }).addTo(map)

    const layer = L.layerGroup().addTo(map)

    const emitBounds = () => {
      const b = map.getBounds()
      onBoundsChange({
        minLatitude: b.getSouth(),
        maxLatitude: b.getNorth(),
        minLongitude: b.getWest(),
        maxLongitude: b.getEast(),
      })
    }

    map.on('moveend', emitBounds)
    map.on('zoomend', emitBounds)
    // Emit initial bounds once the map is ready
    map.whenReady(emitBounds)

    mapRef.current = map
    layerRef.current = layer

    return () => {
      map.remove()
      mapRef.current = null
      layerRef.current = null
    }
  }, [])

  // Redraw markers whenever features change
  useEffect(() => {
    const layer = layerRef.current
    if (!layer) return

    layer.clearLayers()

    for (const f of features) {
      const [lon, lat, depth] = f.geometry.coordinates
      const { mag, place, time, alert, tsunami, url, magType } = f.properties

      const marker = L.circleMarker([lat, lon], {
        radius: magRadius(mag),
        color: depthColor(depth),
        fillColor: depthColor(depth),
        fillOpacity: 0.7,
        weight: 1,
      })

      const alertBadge = alert
        ? `<span style="background:${alert === 'red' ? '#ef4444' : alert === 'orange' ? '#f97316' : alert === 'yellow' ? '#eab308' : '#22c55e'};color:#fff;padding:1px 6px;border-radius:4px;font-size:11px">${alert.toUpperCase()}</span>`
        : ''
      const tsunamiTag = tsunami ? `<span style="color:#3b82f6;font-weight:600"> 🌊 Tsunami</span>` : ''

      marker.bindPopup(`
        <div style="min-width:200px;font-family:sans-serif;font-size:13px">
          <b style="font-size:14px">M${mag} ${magType}</b>${alertBadge}${tsunamiTag}<br/>
          <span style="color:#555">${place}</span><br/>
          <span>Depth: ${depth.toFixed(1)} km</span><br/>
          <span style="color:#888;font-size:11px">${formatTime(time)}</span><br/>
          <a href="${url}" target="_blank" rel="noopener" style="font-size:11px">USGS event page →</a>
        </div>
      `)

      layer.addLayer(marker)
    }
  }, [features])

  return (
    <div
      ref={containerRef}
      style={{ width: '100%', height: '100%' }}
    />
  )
})

MapView.displayName = 'MapView'
export default MapView

import { useRef, useState } from 'react'
import type { EarthquakeFeature } from './api/earthquakes'
import FilterPanel from './components/FilterPanel'
import MapView from './components/MapView'
import type { MapViewHandle } from './components/MapView'
import SearchBar from './components/SearchBar'
import { useEarthquakes } from './hooks/useEarthquakes'

function todayISO() {
  return new Date().toISOString().slice(0, 10)
}

function daysAgoISO(days: number) {
  const d = new Date()
  d.setDate(d.getDate() - days)
  return d.toISOString().slice(0, 10)
}

interface Bounds {
  minLatitude: number
  maxLatitude: number
  minLongitude: number
  maxLongitude: number
}

export default function App() {
  const mapRef = useRef<MapViewHandle>(null)

  const [bounds, setBounds] = useState<Bounds | null>(null)
  const [starttime, setStarttime] = useState(daysAgoISO(7))
  const [endtime, setEndtime] = useState(todayISO())
  const [minmagnitude, setMinmagnitude] = useState(2.5)
  const [sidebarOpen, setSidebarOpen] = useState(true)

  const { data, loading, error, tooMany, tooManyCount } = useEarthquakes(bounds, {
    starttime,
    endtime,
    minmagnitude,
  })

  const features: EarthquakeFeature[] = data?.features ?? []

  return (
    <div className="app-layout">
      {/* Overlay backdrop — mobile only, closes sidebar on tap */}
      {sidebarOpen && (
        <div className="sidebar-backdrop" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`sidebar${sidebarOpen ? ' sidebar--open' : ''}`}>
        <div className="sidebar-header">
          <div>
            <h1 className="app-title">Earthquake Dashboard</h1>
            <p className="app-subtitle">USGS · Live data</p>
          </div>
          {/* Close button — mobile only */}
          <button
            className="sidebar-close"
            onClick={() => setSidebarOpen(false)}
            aria-label="Close panel"
          >✕</button>
        </div>

        <SearchBar mapRef={mapRef} />

        <FilterPanel
          starttime={starttime}
          endtime={endtime}
          minmagnitude={minmagnitude}
          onStarttimeChange={setStarttime}
          onEndtimeChange={setEndtime}
          onMinmagnitudeChange={setMinmagnitude}
          count={features.length}
          loading={loading}
          tooMany={tooMany}
          tooManyCount={tooManyCount}
          error={error}
        />

        <div className="legend">
          <p className="legend-title">Depth</p>
          <div className="legend-item">
            <span className="dot" style={{ background: '#22c55e' }} />
            &lt; 70 km (shallow)
          </div>
          <div className="legend-item">
            <span className="dot" style={{ background: '#f59e0b' }} />
            70–300 km
          </div>
          <div className="legend-item">
            <span className="dot" style={{ background: '#ef4444' }} />
            &gt; 300 km (deep)
          </div>
          <p className="legend-title" style={{ marginTop: 12 }}>Circle size = magnitude</p>
        </div>
      </aside>

      <main className="map-container">
        {/* Hamburger — always visible on mobile, hidden on desktop */}
        {!sidebarOpen && (
          <button
            className="sidebar-toggle"
            onClick={() => setSidebarOpen(true)}
            aria-label="Open panel"
          >☰</button>
        )}
        <MapView
          ref={mapRef}
          features={features}
          onBoundsChange={setBounds}
        />
      </main>
    </div>
  )
}

